#![no_main]

//! Structured mutation of accepted BlindFold proofs.
//!
//! The fixtures are generated by the real ZK prover and include trusted and
//! untrusted advice plus a committed program. Every non-skipped input
//! changes one masked-tape, pad-commitment, final-opening, BlindFold,
//! program-binding, or advice component and requires the compiled ZK
//! verifier to reject it.

use std::sync::OnceLock;

use common::jolt_device::JoltDevice;
use jolt_crypto::{Bn254G1, Pedersen};
use jolt_dory::{DoryCommitment, DoryScheme};
use jolt_algebra::{CanonicalEncoding, Fr, Ring};
use jolt_poly::CompressedPoly;
use jolt_sumcheck::CompressedSumcheckProof;
use jolt_transcript::{Keccak, VerifierState};
use jolt_verifier::{verify, JoltProof, JoltProofClaims, JoltVerifierPreprocessing, ZkConfig};
use libfuzzer_sys::fuzz_target;

type Preprocessing = JoltVerifierPreprocessing<DoryScheme, Pedersen<Bn254G1>>;
type Proof = JoltProof<DoryScheme, Pedersen<Bn254G1>>;
type Bundle = (Preprocessing, JoltDevice, Proof, Option<DoryCommitment>);

static FIXTURES: [&[u8]; 3] = [
    include_bytes!("../fixtures/zk-muldiv-bundle.bin"),
    include_bytes!("../fixtures/zk-committed-muldiv-bundle.bin"),
    include_bytes!("../fixtures/zk-advice-consumer-bundle.bin"),
];

fn bundles() -> &'static [Bundle] {
    static BUNDLES: OnceLock<Vec<Bundle>> = OnceLock::new();
    BUNDLES.get_or_init(|| {
        FIXTURES
            .iter()
            .map(|bytes| {
                let (bundle, consumed): (Bundle, usize) =
                    bincode::serde::decode_from_slice(bytes, bincode::config::standard())
                        .expect("fixture decodes");
                assert_eq!(consumed, bytes.len(), "fixture has trailing bytes");
                let (preprocessing, public_io, proof, advice) = &bundle;
                verify::<Fr, DoryScheme, Pedersen<Bn254G1>, VerifierState<'_, Keccak>>(
                    preprocessing,
                    public_io,
                    proof,
                    advice.as_ref(),
                )
                .expect("honest ZK fixture proof must verify before tampering");
                bundle
            })
            .collect()
    })
}

fn mutate_masked_tape(proof: &mut Proof, operation: u8, index: usize, delta: Fr) -> bool {
    let JoltProofClaims::Zk { masked, zk_proof } = &mut proof.claims else {
        return false;
    };
    match operation % 5 {
        0 => {
            if masked.values.is_empty() {
                return false;
            }
            let position = index % masked.values.len();
            masked.values[position] += delta;
            true
        }
        1 => masked.values.pop().is_some(),
        2 => {
            masked.values.push(delta);
            true
        }
        3 => {
            masked.nonces.push(u64::from(operation));
            true
        }
        _ => zk_proof.pad_commitment.pop().is_some(),
    }
}

fn mutate_compressed(
    proof: &mut CompressedSumcheckProof<Fr>,
    operation: u8,
    index: usize,
    delta: Fr,
) -> bool {
    match operation % 2 {
        0 => proof.round_polynomials.pop().is_some(),
        _ => {
            if proof.round_polynomials.is_empty() {
                return false;
            }
            let round = index % proof.round_polynomials.len();
            let mut coefficients = proof.round_polynomials[round]
                .coeffs_except_linear_term()
                .to_vec();
            let coefficient = operation as usize / 2 % coefficients.len();
            coefficients[coefficient] += delta;
            proof.round_polynomials[round] = CompressedPoly::new(coefficients);
            true
        }
    }
}

fuzz_target!(|data: &[u8]| {
    if data.len() < 5 {
        return;
    }
    let fixture = &bundles()[data[0] as usize % bundles().len()];
    let mut preprocessing = fixture.0.clone();
    let mut public_io = fixture.1.clone();
    let mut proof = fixture.2.clone();
    let mut advice = fixture.3.clone();
    let mutation = data[1] % 16;
    let operation = data[3];
    let index = data[4] as usize;
    let mut delta = Fr::from_bytes_le_reduced(&data[5..data.len().min(37)]);
    if delta == Fr::from_u64(0) {
        delta = Fr::from_u64(1);
    }

    let changed = match mutation {
        // Shape guard, not a soundness probe: ZK claims under a Transparent
        // header are rejected by `validate_proof_consistency` before any
        // crypto runs.
        0 => {
            proof.protocol.zk = ZkConfig::Transparent;
            true
        }
        // Legal-but-wrong dimensions: still powers of two, so they pass
        // `validate_inputs` and must be rejected by the stage round
        // structure rather than a typed shape guard.
        1 => {
            proof.trace_length *= 2;
            true
        }
        2 => {
            proof.ram_K *= 2;
            true
        }
        3 => {
            preprocessing.vc_setup = None;
            true
        }
        4 => mutate_masked_tape(&mut proof, operation, index, delta),
        5 => {
            proof.joint_opening_proof.0.y_com = None;
            true
        }
        6 => {
            let JoltProofClaims::Zk { zk_proof, .. } = &mut proof.claims else {
                return;
            };
            zk_proof.blindfold.folding.random_u += delta;
            true
        }
        7 => {
            let JoltProofClaims::Zk { zk_proof, .. } = &mut proof.claims else {
                return;
            };
            mutate_compressed(&mut zk_proof.blindfold.outer_sumcheck, operation, index, delta)
        }
        8 => {
            let JoltProofClaims::Zk { zk_proof, .. } = &mut proof.claims else {
                return;
            };
            mutate_compressed(&mut zk_proof.blindfold.inner_sumcheck, operation, index, delta)
        }
        9 => {
            let JoltProofClaims::Zk { zk_proof, .. } = &mut proof.claims else {
                return;
            };
            zk_proof.blindfold.folding.random_pad_rows.pop().is_some()
        }
        10 => {
            let JoltProofClaims::Zk { zk_proof, .. } = &mut proof.claims else {
                return;
            };
            zk_proof
                .blindfold
                .folding
                .cross_term_error_rows
                .pop()
                .is_some()
        }
        11 => {
            let JoltProofClaims::Zk { zk_proof, .. } = &mut proof.claims else {
                return;
            };
            zk_proof.blindfold.folded_evaluation.output += delta;
            true
        }
        12 => {
            if public_io.inputs.is_empty() {
                return;
            }
            let position = index % public_io.inputs.len();
            public_io.inputs[position] ^= operation.max(1);
            true
        }
        13 => {
            let before = proof.commitments.rd_inc.clone();
            proof.commitments.rd_inc = DoryCommitment::default();
            proof.commitments.rd_inc != before
        }
        14 => {
            preprocessing.program = bundles()[(data[0] as usize + 1) % bundles().len()]
                .0
                .program
                .clone();
            preprocessing.program != fixture.0.program
        }
        _ => {
            if operation % 2 == 0 {
                advice = match advice.take() {
                    Some(_) => None,
                    None => Some(DoryCommitment::default()),
                };
            } else {
                proof.untrusted_advice_commitment = match proof.untrusted_advice_commitment.take() {
                    Some(_) => None,
                    None => Some(DoryCommitment::default()),
                };
            }
            true
        }
    };
    if !changed {
        return;
    }

    let result = verify::<Fr, DoryScheme, Pedersen<Bn254G1>, VerifierState<'_, Keccak>>(
        &preprocessing,
        &public_io,
        &proof,
        advice.as_ref(),
    );
    assert!(
        result.is_err(),
        "verifier accepted a tampered ZK proof (mutation class {mutation})"
    );
});
